lemma graft_node (e : E) (l r : BTree E) (i : ℕ) (s : BTree E) :
    (node e l r).graft i s =
      if i < l.arity then node e (l.graft i s) r else node e l (r.graft (i - l.arity) s)

lemma restr_two {n : ℕ} (v : Fin n → V) {S : Finset (Fin n)} (h : S.card = 2) {i j : Fin n}
    (hij : i < j) (hi : i ∈ S) (hj : j ∈ S) :
    (fun a => v (S.orderEmbOfFin h a)) = ![v i, v j]

lemma merge_of_mem {a c : ℕ} {S : Finset (Fin (a + c))} (hS : S.card = a) {X : Type*}
    (x : Fin a → X) (y : Fin c → X) {t : Fin (a + c)} (h : t ∈ S) :
    merge S hS x y t = x ((S.orderIsoOfFin hS).symm ⟨t, h⟩)

lemma merge_of_not_mem {a c : ℕ} {S : Finset (Fin (a + c))} (hS : S.card = a) {X : Type*}
    (x : Fin a → X) (y : Fin c → X) {t : Fin (a + c)} (h : t ∉ S) :
    ∃ j, merge S hS x y t = y j

