lemma get?_node_cons_eq_some {k : ℕ} {e : E k} {c : Fin k → STree E} {i : ℕ} {p : List ℕ}
    {u : STree E} :
    (node e c).get? (i :: p) = some u ↔ ∃ hi : i < k, (c ⟨i, hi⟩).get? p = some u

theorem disjoint_of_incomp {A₁ A₂ B : Finset ℕ} {f₁ : SMono E A₁ → SMono E B}
    {f₂ : SMono E A₂ → SMono E B} {ℓ₁ : SMono E A₁} {ℓ₂ : SMono E A₂} {T : SMono E B}
    {p₁ p₂ : List ℕ} {xs₁ xs₂ : ℕ → STree E}
    (hT₁ : T.1.get? p₁ = some (ℓ₁.1.subst xs₁)) (hT₂ : T.1.get? p₂ = some (ℓ₂.1.subst xs₂))
    (hin₁ : Inputs A₁ B xs₁) (hin₂ : Inputs A₂ B xs₂)
    (hf₁ : ∀ g, (f₁ g).1 = T.1.replace p₁ (g.1.subst xs₁))
    (hf₂ : ∀ g, (f₂ g).1 = T.1.replace p₂ (g.1.subst xs₂)) (h : Incomp p₁ p₂) :
    ∃ d : SMono E A₁ → SMono E A₂ → SMono E B, (∀ y, IsSCtx (d · y)) ∧ (∀ x, IsSCtx (d x)) ∧
      f₁ = (d · ℓ₂) ∧ f₂ = d ℓ₁

theorem disjoint_of_nested {A₁ A₂ B : Finset ℕ} {f₁ : SMono E A₁ → SMono E B}
    {f₂ : SMono E A₂ → SMono E B} {ℓ₁ : SMono E A₁} {ℓ₂ : SMono E A₂} {T : SMono E B}
    {p₁ q₀ q'' : List ℕ} {a : ℕ} {xs₁ xs₂ : ℕ → STree E}
    (hT₁ : T.1.get? p₁ = some (ℓ₁.1.subst xs₁)) (hin₁ : Inputs A₁ B xs₁)
    (hin₂ : Inputs A₂ B xs₂) (hf₁ : ∀ g, (f₁ g).1 = T.1.replace p₁ (g.1.subst xs₁))
    (hf₂ : ∀ g, (f₂ g).1 = T.1.replace (p₁ ++ (q₀ ++ q'')) (g.1.subst xs₂))
    (h₀ : ℓ₁.1.get? q₀ = some (leaf a)) (h'' : (xs₁ a).get? q'' = some (ℓ₂.1.subst xs₂)) :
    ∃ d : SMono E A₁ → SMono E A₂ → SMono E B, (∀ y, IsSCtx (d · y)) ∧ (∀ x, IsSCtx (d x)) ∧
      f₁ = (d · ℓ₂) ∧ f₂ = d ℓ₁

lemma get?_input {U ℓ : STree E} {p : List ℕ} {xs : ℕ → STree E}
    (hU : U.get? p = some (ℓ.subst xs)) {a : ℕ} (ha : a ∈ ℓ.labels) :
    U.get? (p ++ ℓ.pos a) = some (xs a)

theorem inputs_of_occ {A B : Finset ℕ} (U : SMono E B) {p : List ℕ} {ℓ : SMono E A}
    {xs : ℕ → STree E} (hU : U.1.get? p = some (ℓ.1.subst xs))
    (hm : StrictMonoOn (fun a => (xs a).first) (A : Set ℕ)) : Inputs A B xs

theorem pathLexBy_ctx {W : List L → List L → Prop}
    (hW : ∀ {u w}, W u w → ∀ P Q, W (P ++ (u ++ Q)) (P ++ (w ++ Q))) {A B : Finset ℕ}
    {f : SMono E A → SMono E B} (hf : IsSCtx f) {x y : SMono E A} (h : pathLexBy ltr W x y) :
    pathLexBy ltr W (f x) (f y)

lemma graftF_cons {k : ℕ} (t : Tree E) (f : Forest E k) (i : ℕ) (s : Tree E) :
    (Forest.cons t f).graftF i s =
      if i < t.arity then .cons (t.graft i s) f else .cons t (f.graftF (i - t.arity) s)

lemma app_eq_chart (φ : SetSpeciesHom X Y) {A : Type} [Fintype A] [DecidableEq A] {n : ℕ}
    (e : Fin n ≃ A) (x : X A) :
    φ.app A x = SetSpecies.map e (φ.app (Fin n) (SetSpecies.map e.symm x))

@[ext] lemma ext {φ ψ : SetSpeciesHom X Y}
    (h : ∀ (A : Type) [Fintype A] [DecidableEq A] (x : X A), φ.app A x = ψ.app A x) :
    φ = ψ

lemma extendApp_chart {f : ∀ n : ℕ, X (Fin n) → Y (Fin n)} (hf : Equivariant f) {A : Type}
    [Fintype A] [DecidableEq A] {n : ℕ} (φ : Fin n ≃ A) (x : X A) :
    extendApp f A x = SetSpecies.map φ (f n (SetSpecies.map φ.symm x))

