    (g : Syn T (Fin 2)) (x : Syn T A) (y : Syn T B) :
    Pres.mk (ρ := ρ) (Syn.bin g x y) = SetOperad.bin (Pres.mk g) (Pres.mk x) (Pres.mk y)

lemma subst3_absurd {A B : Type} [DecidableEq A] (ℓ : Fin 3 ≃ L) {l : L} {h0 : l ≠ ℓ 0}
    {h1 : (Sum.inl ⟨l, h0⟩ : Without L (ℓ 0) ⊕ A) ≠ subst3Slot₂ ℓ A}
    (h2 : (Sum.inl ⟨Sum.inl ⟨l, h0⟩, h1⟩ : Without (Without L (ℓ 0) ⊕ A) (subst3Slot₂ ℓ A) ⊕ B)
      ≠ subst3Slot₃ ℓ A B) : False

lemma graft_node_succ (e : E) (a : ℕ) (f : E) (l r : LTree E) (p : ℕ) :
    graft e a (node f l r) (p + 1) =
      if p < l.size then node f (graft e a l p) r else node f l (graft e a r (p - l.size))

theorem pathKey_substAt_lt (rk : E → ℕ) {n : ℕ} {t : LTree E} {p : List Bool} {s : Bool}
    (he : t.IsEdge p s) (hs : t.IsShuffle) (ht : t.labels.Perm (List.range n)) {m m' : LTree E}
    (hm : m.labels.Perm (List.range 3)) (hm' : m'.labels.Perm (List.range 3))
    (h : pathKey rk 3 m < pathKey rk 3 m') :
    pathKey rk n (t.substAt p s m) < pathKey rk n (t.substAt p s m')

